import 'package:cephalopod/core/board/models/board_ui.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'demo_frame_ui.freezed.dart';

/// One moment of Home's demo: the [board] on show, and how long it stays
/// there ([hold]) before the next.
///
/// A UI model (docs/adr/0015): plain data generated by freezed
/// (docs/adr/0011).
@freezed
abstract class DemoFrameUi with _$DemoFrameUi {
  const factory DemoFrameUi({
    required BoardUi board,
    required Duration hold,
  }) = _DemoFrameUi;
}
